INSERT INTO call_record (
    biz_type, caller_id, caller_name, caller_type, caller_level,
    caller_dept_code, caller_dept_name, req_summary, resp_summary,
    cost_time_ms, result_status, error_code
) VALUES

    (
    #{item.bizType}, #{item.callerId}, #{item.callerName}, #{item.callerType}, #{item.callerLevel},
    #{item.callerDeptCode}, #{item.callerDeptName}, #{item.reqSummary}, #{item.respSummary},
    #{item.costTimeMs}, #{item.resultStatus}, #{item.errorCode}
    )

mapper.select:
SELECT MAX(${dimColumn}) AS name, COUNT(*) AS value
FROM call_record
WHERE gmt_create >= #{start}
  AND gmt_create <= #{end}
GROUP BY ${groupBy}
ORDER BY value DESC

SELECT ${timeExpr} AS time,
       COUNT(*) AS calls,
       SUM(CASE WHEN result_status = 'SUCCESS' THEN 1 ELSE 0 END) AS successCount
FROM call_record
WHERE gmt_create >= #{start}
  AND gmt_create <= #{end}

  AND ${dimColumn} = #{dimValue}

GROUP BY time
ORDER BY time ASC

SELECT
    id, biz_type, caller_id, caller_name, caller_type, caller_level,
    caller_dept_code, caller_dept_name, req_summary, resp_summary,
    cost_time_ms, result_status, error_code, gmt_create, gmt_modified
FROM call_record
WHERE biz_type = #{bizType}
  AND gmt_create >= #{start}
  AND gmt_create <= #{end}
ORDER BY gmt_create DESC, id DESC
LIMIT #{limit}
